<?php require_permission('logistics.approve'); $rows=$pdo->query("SELECT l.*,u.unit_code,req.name requester,app.name approver FROM logistics_orders l LEFT JOIN units u ON u.id=l.unit_id LEFT JOIN users req ON req.id=l.requested_by LEFT JOIN users app ON app.id=l.approved_by WHERE l.approval_status IN ('Menunggu Approval','Disetujui','Ditolak') ORDER BY FIELD(l.approval_status,'Menunggu Approval','Disetujui','Ditolak'),l.created_at DESC")->fetchAll(); ?>
<div class="card panel"><h3>Approval Permintaan Spare Part</h3><table><thead><tr><th>No Permintaan</th><th>Unit</th><th>Barang</th><th>Qty</th><th>Nilai</th><th>Pemohon</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['request_no'])?></td><td><?=e($r['unit_code']??'-')?></td><td><?=e($r['item_name'])?></td><td><?=$r['quantity']?></td><td><?=rupiah($r['total_cost'])?></td><td><?=e($r['requester']??'-')?></td><td><span class="status <?=status_class($r['approval_status'])?>"><?=e($r['approval_status'])?></span></td><td><?php if($r['approval_status']==='Menunggu Approval'):?><form class="inline" method="post" action="actions/approve_sparepart.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link" name="decision" value="approve">Setujui</button> · <button class="link danger" name="decision" value="reject">Tolak</button></form><?php else:?><?=e($r['approver']??'-')?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
